 const before=sqlite.prepare('SELECT revision FROM hris_workspaces').get().revision;sqlite.exec("CREATE TRIGGER fail_hire_audit BEFORE INSERT ON hris_audit_events BEGIN SELECT RAISE(ABORT,'audit unavailable'); END");await recruit({action:'hire',id:candidate.id,code:'NEW1'},503);assert.equal(sqlite.prepare('SELECT revision FROM hris_workspaces').get().revision,before);assert.equal(sqlite.prepare("SELECT count(*) n FROM hris_employees WHERE code='NEW1'").get().n,0);assert.equal((await expect(await recruitment.GET())).records.find(r=>r.id===candidate.id).status,'accepted');sqlite.exec('DROP TRIGGER fail_hire_audit');
 await recruit({action:'hire',id:candidate.id,code:'NEW1'});let state=(await expect(await hris.GET())).state;const hired=state.employees.find(x=>x.code==='NEW1');assert.ok(hired);assert.equal(hired.positionId,position.id);assert.equal(hired.email,'candidate-private@example.com');assert.equal(sqlite.prepare('SELECT count(*) n FROM hris_employment_history WHERE employee_id=?').get(hired.id).n,1);assert.equal((await expect(await recruitment.GET())).records.find(r=>r.id===candidate.id).payload.hiredEmployeeId,hired.id);await recruit({action:'hire',id:candidate.id,code:'NEW2'},400);assert.equal((await expect(await hris.GET())).state.employees.length,3);
 const extra=await recruit({action:'candidate',requisitionId:req.id,name:'另一合成候选人',email:'',source:'独立投递来源编号 SYNTHETIC-002'});act('manager');await recruit({action:'interview',candidateId:extra.id,rating:3,recommendation:'advance',evidence:'完成岗位案例评价并建议继续推进'});act('owner');await recruit({action:'offer',id:extra.id,joined:'2026-01-01',evidence:'申请录用，仍需检查需求剩余名额'});act('manager');await recruit({action:'approveOffer',id:extra.id});act('owner');await recruit({action:'acceptOffer',id:extra.id,evidence:'已记录第二名候选人的接受依据'});await recruit({action:'hire',id:extra.id,code:'EXTRA'},400);await recruit({action:'rejectCandidate',id:extra.id,reason:'招聘需求人数已满，经沟通结束流程'});await recruit({action:'closeRequisition',id:req.id,reason:'批准招聘人数已经全部完成入职'});act('employee');assert.equal((await expect(await recruitment.GET())).records.length,0);await expect(await dev.GET(request('/api/development?id='+candidate.id)),403);assert.ok(e.id!==hired.id);sqlite.close();
