test('P3 假勤：休息扣除、待批余额占用、撤回释放、独立审批及补卡保留原始记录',async()=>{
 const {sqlite,e,other}=await setup();const shift=await attend({action:'shift',employeeId:e.id,date:'2026-01-05',name:'标准白班',startAt:'2026-01-05T09:00:00+08:00',endAt:'2026-01-05T18:00:00+08:00',breakStart:'2026-01-05T12:00:00+08:00',breakEnd:'2026-01-05T13:00:00+08:00'});await attend({action:'shift',employeeId:e.id,date:'2026-01-05',name:'重叠班次',startAt:'2026-01-05T10:00:00+08:00',endAt:'2026-01-05T19:00:00+08:00'},400);const type=await attend({action:'leaveType',code:'PAID2026',name:'企业批准带薪假',paid:true,requiresBalance:true});await attend({action:'leaveCredit',employeeId:e.id,leaveTypeId:type.id,year:2026,minutes:480,source:'已审核假期台账来源编号 BALANCE-001'});act('employee');const leave=await attend({action:'leave',employeeId:e.id,shiftId:shift.id,leaveTypeId:type.id,startAt:'2026-01-05T09:00:00+08:00',endAt:'2026-01-05T14:00:00+08:00',reason:'已与团队协调安排个人事务请假'});let d=await expect(await attendance.GET());assert.ok((await expect(await selfService.GET())).requests.some(r=>r.id===leave.id&&r.status==='pending'));assert.equal(d.balances[0].reserved,240);assert.equal(d.balances[0].available,240);await attend({action:'decideLeave',id:leave.id,accepted:true,evidence:'本人不能审批自己的请假'},403);await attend({action:'leave',employeeId:e.id,shiftId:shift.id,leaveTypeId:type.id,startAt:'2026-01-05T13:00:00+08:00',endAt:'2026-01-05T18:00:00+08:00',reason:'重叠申请必须被拒绝避免重复占用'},400);await attend({action:'withdrawLeave',id:leave.id,reason:'工作安排调整，先撤回请假申请'});d=await expect(await attendance.GET());assert.equal(d.balances[0].available,480);const full=await attend({action:'leave',employeeId:e.id,shiftId:shift.id,leaveTypeId:type.id,startAt:'2026-01-05T09:00:00+08:00',endAt:'2026-01-05T18:00:00+08:00',reason:'重新提交全天请假，工作已经交接'});act('owner');await attend({action:'leaveCredit',employeeId:e.id,leaveTypeId:type.id,year:2026,minutes:-1,source:'待批额度已经占满，不能再扣减余额'},400);act('manager');await attend({action:'decideLeave',id:full.id,accepted:true,evidence:'已核实工作交接和可用假期，批准'});d=await expect(await attendance.GET());assert.equal(d.report[0].plannedMinutes,480);assert.equal(d.report[0].approvedLeaveMinutes,480);assert.equal(d.report[0].uncoveredMinutes,0);assert.equal(d.report[0].status,'请假覆盖');await attend({action:'decideLeave',id:full.id,accepted:true,evidence:'重复审批不得重复扣减余额'},400);await attend({action:'cancelApprovedLeave',id:full.id,reason:'员工最终未休假，依据出勤记录取消批准'});d=await expect(await attendance.GET());assert.equal(d.balances[0].available,480);
 act('employee');const correction=await attend({action:'correction',shiftId:shift.id,inAt:'2026-01-05T09:00:00+08:00',outAt:'2026-01-05T18:00:00+08:00',evidence:'门禁和项目记录证明当天按时出勤'});await attend({action:'decideCorrection',id:correction.id,accepted:true,evidence:'本人不能自审补卡'},403);act('manager');await attend({action:'decideCorrection',id:correction.id,accepted:true,evidence:'已核对门禁与项目记录，确认补卡'});d=await expect(await attendance.GET());assert.equal(d.report[0].uncoveredMinutes,0);assert.equal(d.report[0].corrected,true);assert.equal(d.records.filter(r=>r.kind==='clock').length,0);assert.equal(d.report[0].status,'记录完整');await attend({action:'shift',employeeId:other.id,date:'2026-01-05',name:'越权排班',startAt:'2026-01-05T09:00:00+08:00',endAt:'2026-01-05T18:00:00+08:00'},403);act('employee');assert.ok((await expect(await attendance.GET())).records.every(r=>!r.employeeId||r.employeeId===e.id));sqlite.close();
});
