test('P3 360：指定评估人、人数阈值、低样本隐藏、冻结后发布及被评人不读取原始答卷',async()=>{
 const {sqlite,e,org}=await setup();const people=[];for(let i=0;i<4;i++){await core({action:'employee',code:'FB'+i,name:'反馈参与者'+i,orgId:org.id,job:'测试',level:'',email:'',joined:'2026-01-01'});const person=(await expect(await hris.GET())).state.employees.find(x=>x.code==='FB'+i);people.push(person);await grant('fb'+i,'employee',person.id);}
 const template=await survey({action:'template',code:'360T',name:'领导行为量表',description:'按可观察的日常管理行为给予反馈',questions:[{type:'rating',prompt:'能否清晰说明工作目标',lowLabel:'很少做到',highLabel:'持续做到'}]});await survey({action:'publishTemplate',id:template.id});const p=await fb({action:'project',name:'领导行为360项目',orgId:org.id,templateId:template.id,start:'2020-01-01',end:'2099-12-31',purpose:'HR可审计实名答卷，被评人只查看符合人数要求的分组汇总',minRespondents:3});const invites=[[],[]];for(let i=0;i<3;i++)for(let j=0;j<2;j++)invites[j].push(await fb({action:'invite',projectId:p.id,subjectId:j?people[3].id:e.id,reviewerEmployeeId:people[i].id,relationship:'peer'}));await fb({action:'invite',projectId:p.id,subjectId:e.id,reviewerEmployeeId:e.id,relationship:'peer'},400);act('fb0');assert.ok(!(await get()).records.some(x=>x.id===p.id));act('owner');await fb({action:'open',id:p.id});await fb({action:'publishReport',projectId:p.id,subjectId:e.id,evidence:'未锁定答卷不能提前发布报告'},400);
 for(let i=0;i<3;i++){act('fb'+i);if(i<2)await fb({action:'respond',inviteId:invites[0][i].id,answers:[i+1]});await fb({action:'respond',inviteId:invites[1][i].id,answers:[i+2]});if(i===0){await fb({action:'respond',inviteId:invites[1][1].id,answers:[5]},403);assert.ok(!(await get()).records.some(x=>x.id===invites[1][1].id));}}
 act('employee');assert.ok(!(await get()).records.some(x=>x.kind==='feedbackReply'));act('owner');await fb({action:'close',id:p.id,evidence:'按计划结束收集并锁定全部已交答卷'});act('fb0');await fb({action:'respond',inviteId:invites[0][0].id,answers:[5]},400);act('owner');const r1=await fb({action:'publishReport',projectId:p.id,subjectId:e.id,evidence:'发布低样本隐藏后的分组反馈'});const r2=await fb({action:'publishReport',projectId:p.id,subjectId:people[3].id,evidence:'发布满足人数要求的分组反馈'});await fb({action:'publishReport',projectId:p.id,subjectId:e.id,evidence:'不能重复发布生成可差分的报告'},400);
 act('employee');let d=await expect(await feedback.GET()),report=d.records.find(x=>x.id===r1.id),peer=report.payload.feedbackGroups.find(g=>g.relationship==='peer');assert.equal(peer.responses,2);assert.equal(peer.suppressed,true);assert.equal(peer.averages,null);assert.ok(!d.records.some(x=>['feedbackInvite','feedbackReply'].includes(x.kind)));assert.ok(people.slice(0,3).every(person=>!JSON.stringify(report).includes(person.id)));const history=await expect(await dev.GET(request('/api/development?id='+r1.id)));assert.equal(history.items[0].snapshot.payload.feedbackGroups.find(g=>g.relationship==='peer').averages,null);act('fb3');report=(await expect(await feedback.GET())).records.find(x=>x.id===r2.id);peer=report.payload.feedbackGroups.find(g=>g.relationship==='peer');assert.equal(peer.responses,3);assert.equal(peer.suppressed,false);assert.deepEqual(peer.averages,[3]);act('manager');assert.ok(!(await get()).records.some(x=>['feedbackReport','feedbackReply'].includes(x.kind)));sqlite.close();
});
