test('P3 自定义档案：正式值和申请隔离、字段可见范围、独立复核、类型校验与停用',async()=>{
 const {sqlite,e,other,org}=await setup();const def=await field({action:'define',code:'preferred_city',name:'意向城市',description:'员工提供后由HR复核登记',fieldType:'choice',fieldOptions:['上海','北京'],employeeRead:true,managerRead:true,employeeEditable:true});const secret=await field({action:'define',code:'hr_note',name:'内部备注',description:'仅HR可见的业务记录字段',fieldType:'text'});
 const v=await field({action:'record',definitionId:def.id,employeeId:e.id,value:'上海',evidence:'经员工提供材料核实登记'});const hidden=await field({action:'record',definitionId:secret.id,employeeId:e.id,value:'合成保密记录',evidence:'仅作权限隔离验证的合成数据'});
 act('hr');await field({action:'record',definitionId:def.id,employeeId:other.id,value:'北京',evidence:'跨组织维护必须被拒绝'},403);
 act('employee');assert.ok(!(await get()).records.some(r=>r.id===secret.id||r.id===hidden.id));await expect(await dev.GET(request('/api/development?id='+hidden.id)),403);await field({action:'propose',definitionId:def.id,value:'深圳',evidence:'选项外的值不能写入'},400);await field({action:'propose',definitionId:secret.id,value:'尝试越权',evidence:'员工不能修改内部字段'},403);await field({action:'propose',definitionId:def.id,value:'北京',evidence:'员工提出意向城市变更'});let d=await expect(await employeeFields.GET());assert.equal(d.records.find(r=>r.id===v.id).payload.fieldValue,'上海');assert.equal(d.records.find(r=>r.id===v.id).payload.pendingValue,'北京');
 act('manager');d=await expect(await employeeFields.GET());const projected=d.records.find(r=>r.id===v.id);assert.equal(projected.status,'active');assert.equal(projected.payload.fieldValue,'上海');assert.ok(!('pendingValue'in projected.payload));assert.ok(!d.records.some(r=>r.id===hidden.id));await expect(await dev.GET(request('/api/development?id='+v.id)),403);await field({action:'review',id:v.id,accepted:true,evidence:'经理不具备字段复核权限'},403);
 act('owner');await grant('employee','hr',e.id,[org.id],true);act('employee');await field({action:'review',id:v.id,accepted:true,evidence:'本人即使成为HR也不能自审'},403);await field({action:'record',definitionId:def.id,employeeId:e.id,value:'北京',evidence:'本人不能直接改写正式值'},403);
 act('hr');const rev=(await expect(await employeeFields.GET())).revision;await field({action:'review',id:v.id,accepted:true,evidence:'独立核实员工提交材料后通过'});assert.equal((await get()).records.find(r=>r.id===v.id).payload.fieldValue,'北京');await field({action:'record',definitionId:def.id,employeeId:e.id,value:'上海',evidence:'旧版本不能覆盖刚完成的复核'},409,rev);await field({action:'review',id:v.id,accepted:true,evidence:'重复复核必须被拒绝'},400);
 act('employee');await field({action:'propose',definitionId:def.id,value:null,evidence:'员工申请清空意向城市'});act('owner');await field({action:'archive',id:def.id});act('hr');await field({action:'review',id:v.id,accepted:true,evidence:'停用后不能使申请生效'},400);await field({action:'review',id:v.id,accepted:false,evidence:'字段已经停用，保留原正式值'});assert.equal((await get()).records.find(r=>r.id===v.id).payload.fieldValue,'北京');await field({action:'define',code:'PREFERRED_CITY',name:'重复编码',description:'停用之后也不能重用编码',fieldType:'text'},400);
 const date=await field({action:'define',code:'review_date',name:'核验日期',description:'记录内部核验日期信息',fieldType:'date'});await field({action:'record',definitionId:date.id,employeeId:e.id,value:'2026-02-30',evidence:'不存在的日期不得保存'},400);sqlite.close();
});
test('P3 绩效申诉：独立复核、发布分离、原快照保留、最新结果报表和历史隔离',async()=>{
 const {sqlite,e,org,otherOrg}=await setup();const cy=await perf({action:'cycle',name:'申诉验证周期',orgId:org.id,period:'APPEAL-2026',start:'2026-01-01',end:'2026-12-31',lowCut:60,highCut:80,lowLabel:'待改进',midLabel:'达成',highLabel:'优秀'});await perf({action:'startCycle',id:cy.id});act('employee');const plan=await perf({action:'goals',employeeId:e.id,cycleId:cy.id,goals:[{title:'交付质量',metric:'按已确认验收标准核对项目成果',weight:60},{title:'团队协作',metric:'按已确认共享记录核对协作成果',weight:40}]});act('manager');await perf({action:'confirmGoals',id:plan.id});act('employee');await perf({action:'selfReview',id:plan.id,evidence:'已提交本周期实际项目和协作记录'});act('manager');await perf({action:'evaluate',id:plan.id,scores:[60,70],evidence:'按已收到材料完成目标评价'});act('owner');const result=await perf({action:'publishPerformance',id:plan.id,evidence:'完成原始评价核对并发布结果'});const review=await send({action:'review',employeeId:e.id,period:'APPEAL-2026',performanceId:result.id,potential:2,evidence:'使用原始正式结果开展人才盘点'});await send({action:'publishReview',id:review.id});await perf({action:'closeCycle',id:cy.id});
 act('employee');const withdrawn=await perf({action:'appeal',resultId:result.id,evidence:'申请核对遗漏的项目验收材料'});await perf({action:'withdrawAppeal',id:withdrawn.id,evidence:'先补充完整材料，再正式提交'});const appeal=await perf({action:'appeal',resultId:result.id,evidence:'申诉私密材料：补充遗漏验收证据'});await perf({action:'appeal',resultId:result.id,evidence:'重复申诉不得创建第二个待办'},400);await perf({action:'reviewAppeal',id:appeal.id,accepted:true,scores:[90,80],evidence:'本人不能复核自己的申诉'},403);
 act('manager');assert.ok(!(await get()).records.some(r=>r.id===appeal.id));await expect(await dev.GET(request('/api/development?id='+appeal.id)),403);act('owner');await perf({action:'reviewAppeal',id:appeal.id,accepted:true,scores:[90,80],evidence:'原发布人不得独立复核'},403);await grant('outsidehr','hr',null,[otherOrg.id]);act('outsidehr');await perf({action:'reviewAppeal',id:appeal.id,accepted:true,scores:[90,80],evidence:'跨组织HR不得复核申诉'},403);await grant('manager','hr',null,[org.id],true);act('manager');await perf({action:'reviewAppeal',id:appeal.id,accepted:true,scores:[90,80],evidence:'原评价人即使成为HR也不能复核'},403);
 act('hr');await perf({action:'reviewAppeal',id:appeal.id,accepted:true,scores:[90],evidence:'评分必须与原目标数量一致'},400);await perf({action:'reviewAppeal',id:appeal.id,accepted:true,scores:[90,80],evidence:'已独立核实补充材料，按原权重更正'});assert.equal((await get()).records.find(r=>r.id===result.id).payload.score,64);await perf({action:'publishCorrection',id:appeal.id,evidence:'复核人与发布人须分别办理'},403);act('employee');await perf({action:'withdrawAppeal',id:appeal.id,evidence:'已审结申诉不能再次撤回'},400);act('owner');const corrected=await perf({action:'publishCorrection',id:appeal.id,evidence:'核对独立复核结论后发布更正版本'});await perf({action:'publishCorrection',id:appeal.id,evidence:'重复发布不得新增第二份结果'},400);let d=await get();assert.equal(d.records.find(r=>r.id===corrected.id).payload.score,86);assert.equal(d.records.find(r=>r.id===corrected.id).payload.supersedes,result.id);assert.equal(d.records.find(r=>r.id===result.id).payload.score,64);assert.equal(d.records.find(r=>r.id===review.id).payload.performanceSnapshot.score,64);assert.equal(d.records.find(r=>r.id===plan.id).payload.score,64);assert.equal(d.records.find(r=>r.id===corrected.id).payload.performanceSnapshot.plan.goals[0].weight,60);
 await send({action:'review',employeeId:e.id,period:'APPEAL-2026',performanceId:result.id,potential:2,evidence:'更正后新盘点不得使用旧版本'},400);const report=await expect(await reports.GET(request('/api/reports?dataset=performance')));assert.equal(report.rows.length,1);assert.ok(JSON.stringify(report.rows).includes('86'));act('employee');assert.equal((await expect(await selfService.GET())).requests.find(r=>r.id===appeal.id).status,'corrected');await perf({action:'appeal',resultId:result.id,evidence:'不得对旧版本再次发起申诉'},400);const again=await perf({action:'appeal',resultId:corrected.id,evidence:'对最新结果申请第二次独立核对'});act('manager');await perf({action:'reviewAppeal',id:again.id,accepted:false,evidence:'核实原目标及证据，维持本版本结果'});assert.equal((await get()).records.find(r=>r.id===again.id).status,'upheld');await grant('manager','manager',null,[org.id],true);act('manager');const visible=(await get()).records.find(r=>r.id===corrected.id);assert.ok(!JSON.stringify(visible).includes('申诉私密材料'));sqlite.close();
});
