test('P3 学习学分：课程版本固定、成果核验前置、授予唯一、独立撤销及范围隔离',async()=>{
 const {sqlite,e,other}=await setup();const course=await send({action:'course',code:'CREDIT',title:'学分验证课程',description:'完成课程实践后核验学习成果',content:'阅读学习案例并完成实际练习，提交成果材料，由独立管理人员核验后登记学分。'});const policy=await credit({action:'policy',courseId:course.id,creditUnits:125,evidence:'依据合成课程学分标准配置'});await credit({action:'policy',courseId:course.id,creditUnits:200,evidence:'同课程版本不能重复配置学分'},400);act('employee');assert.ok(!(await get()).records.some(r=>r.id===policy.id));await expect(await dev.GET(request('/api/development?id='+policy.id)),403);act('owner');await send({action:'publishCourse',id:course.id});const enrollment=await send({action:'enroll',courseId:course.id,employeeId:e.id,due});const otherEnrollment=await send({action:'enroll',courseId:course.id,employeeId:other.id,due});await credit({action:'award',enrollmentId:enrollment.id,evidence:'未完成核验不能登记学分'},400);act('employee');await send({action:'submitLearning',id:enrollment.id,evidence:'已完成课程练习并提交实践证据'});act('manager');await send({action:'verifyLearning',id:enrollment.id,accepted:true,evidence:'独立核实实践成果，确认完成学习'});await credit({action:'award',enrollmentId:enrollment.id,evidence:'经理不具有学分台账写入权限'},403);act('hr');await credit({action:'award',enrollmentId:otherEnrollment.id,evidence:'不能为其他组织员工登记学分'},403);act('owner');const award=await credit({action:'award',enrollmentId:enrollment.id,evidence:'核对课程版本及学习完成记录'});await credit({action:'award',enrollmentId:enrollment.id,evidence:'不得重复授予同一学习记录'},400);await credit({action:'reverse',awardId:award.id,evidence:'授予人不得独立撤销自己的记录'},403);act('employee');let d=await expect(await learningCredits.GET());assert.equal(d.summary[0].netUnits,125);assert.ok(d.records.some(r=>r.id===award.id));await credit({action:'reverse',awardId:award.id,evidence:'员工不能撤销本人的学分'},403);act('hr');const stale=(await get()).revision;await credit({action:'reverse',awardId:award.id,evidence:'独立核实登记依据有误，撤销学分'});await credit({action:'reverse',awardId:award.id,evidence:'重复撤销不能产生负学分'},400);d=await expect(await learningCredits.GET());assert.equal(d.summary[0].netUnits,0);assert.equal(d.summary[0].awardedUnits,125);assert.equal(d.summary[0].reversedUnits,125);assert.equal((await get()).records.find(r=>r.id===enrollment.id).status,'completed');await credit({action:'award',enrollmentId:enrollment.id,evidence:'已撤销的原学习记录也不能重复授予'},400);const next=await send({action:'course',code:'CREDIT',title:'学分验证课程新版',description:'新版本采用独立的课程要求',content:'新版本课程使用独立要求，完成案例实践并提交成果，由管理人员独立核验学习效果。'});await credit({action:'policy',courseId:next.id,creditUnits:200,evidence:'旧版本快照不得覆盖并发更新'},409,stale);await credit({action:'policy',courseId:next.id,creditUnits:200,evidence:'新课程版本独立配置学分标准'});assert.equal((await get()).records.find(r=>r.id===policy.id).payload.creditUnits,125);sqlite.close();
});
