 act('owner');const version=await send({action:'course',code:'TEACH',title:'讲师课程第二版',description:'升级内容后须重新认证课程版本',content:'本次升级增加案例与教学标准，原课程版本认证不自动迁移。'});await send({action:'publishCourse',id:version.id});const t2=await send({action:'training',name:'新版课程培训',orgId:org.id,period:'2099',start:'2099-01-01',end:due,instructor:'测试讲师',courseIds:[version.id]});await send({action:'publishTraining',id:t2.id});await session({...base,trainingId:t2.id,courseId:version.id,instructorCertificationId:later.id,startAt:'2099-08-01T09:00:00+08:00',endAt:'2099-08-01T12:00:00+08:00'},400);act('hr');await instructor({...input,employeeId:other.id},403);sqlite.close();
